supplied_sources.excerpt:
// FIX 2026-05-05: per-symbol price tracking for cross-asset equity.
// Dual-broker emits may carry .symbol on the wrapper; if absent,
// infer from the active session's primary symbol. Either source
// gets normalized to dash-form before storing.
if (!sym) {
  console.error(`[VIS][OHLC][Runner] dropped ${tf} SessionRouter candle: missing symbol | session=${this.sessionRouter?.activeSession || '(none)'} contexts=${describeSymbolContexts(this.symbolContexts)}`);
  return;
}
emitTrace(this, 'CANDLE_NORMALIZED', {
  traceId,
  source: `sessionRouter:${this.sessionRouter?.activeSession || 'unknown'}`,
  symbol: sym,
  timeframe: tf,
  close: ohlcData[5],
  etime: ohlcData[1],
});
this.lastBrokerDataReceived = Date.now();
this.lastBrokerDataSymbol = sym;
this.lastBrokerDataTimeframe = tf;
const activeTf = (this.timeframeSelector && this.timeframeSelector.currentTimeframe) || this.candleTimeframe;
let markUpdated = false;
if (stateManager && stateManager.updateLastPrice) {
  markUpdated = stateManager.updateLastPrice(sym, ohlcData[5], ohlcData[1]);
}
emitTrace(this, 'LAST_PRICE_INFLUENCE', {
  traceId,
  source: `sessionRouter:${this.sessionRouter?.activeSession || 'unknown'}`,
  symbol: sym,
  sourceTimeframe: tf,
  activeTimeframe: activeTf,
  close: ohlcData[5],
  eventTime: ohlcData[1],
  markUpdated,
  strategyRouted: tf === activeTf,
  influence: tf === activeTf ? 'mark_and_strategy' : 'mark_only',
});
this._visOhlcSeen ??= new Set();
const visKey = `session:${this.sessionRouter?.activeSession || 'unknown'}:${sym}:${tf}`;
if (!this._visOhlcSeen.has(visKey) || tf === activeTf) {
  this._visOhlcSeen.add(visKey);
  console.log(`[VIS][OHLC][Runner] source=sessionRouter session=${this.sessionRouter?.activeSession || '(none)'} timeframe=${tf} symbolSource=${symbolSource} payloadSymbol=${eventSymbol || rawSymbol || '(missing)'} symbol=${sym} close=${ohlcData[5]} contexts=${describeSymbolContexts(this.symbolContexts)}`);
}
const storedCandle = this.storeTimeframeCandle(tf, ohlcData, sym);
this.storeSymbolTimeframeCandle(sym, tf, ohlcData);
if (tf === activeTf) {
  this._markActiveTimeframeData(sym, tf);
  const scopeEnvelope = this.getCandleScopeEnvelope({
    brokerId: this.sessionRouter?.activeBroker?.id || null,
    assetClass: this.sessionRouter?.activeSession === 'crypto'
      ? 'crypto'
      : this.sessionRouter?.activeSession === 'stocks'
        ? 'stocks'
        : null,
    timeframe: tf,
  });
  this.syncDashboardRuntimeScope(sym, scopeEnvelope);
  this.handleMarketData({
    data: ohlcData,
    symbol: sym,
    timeframe: tf,
    traceId,
    ...scopeEnvelope,
  });
} else {
  this.timeframeDiagnostics.nonActiveTimeframeDrops += 1;
  console.error(`[OHLC][TIMEFRAME-NON-ACTIVE] dropped non-active timeframe payload count=${this.timeframeDiagnostics.nonActiveTimeframeDrops} symbol=${sym} sourceTimeframe=${tf} activeTimeframe=${activeTf}`);
  emitTrace(this, 'NON_ACTIVE_TIMEFRAME_DROPPED', {
    traceId,
    source: `sessionRouter:${this.sessionRouter?.activeSession || 'unknown'}`,
    symbol: sym,
    sourceTimeframe: tf,
    activeTimeframe: activeTf,
    reason: 'tfe_owns_bar_production',
  });
}
if (tf === '5m' && this.timeframeSelector) {

'use strict';

describe('active timeframe aggregate fallback removal', () => {
  function runEmpireSource() {
    const fs = require('fs');
    const path = require('path');
    return fs.readFileSync(path.resolve(__dirname, '..', 'run-empire-v2.js'), 'utf8');
  }

  test('runner does not own private active-timeframe aggregation fallback', () => {
    const source = runEmpireSource();

    expect(source).not.toContain('_feedAggregatedActiveCandle');
    expect(source).not.toContain('_requestAggregateSourceBackfill');
    expect(source).not.toContain('_trimAggregateTrackingSets');
    expect(source).not.toContain('_emittedAggregatedActiveCandles');
    expect(source).not.toContain('_settledAggregatedActiveCandles');
    expect(source).not.toContain('_aggregateSourceBackfills');
    expect(source).not.toContain('ACTIVE_CANDLE_AGGREGATED');

    expect(source).toContain('this.timeframeDiagnostics.nonActiveTimeframeDrops += 1');
    expect(source).toContain('[OHLC][TIMEFRAME-NON-ACTIVE] dropped non-active timeframe payload');
  });

  test('non-active timeframe path drops loudly instead of synthesizing active candles', () => {
    const source = runEmpireSource();
    const dropIndex = source.indexOf('[OHLC][TIMEFRAME-NON-ACTIVE] dropped non-active timeframe payload');
    const handleIndex = source.indexOf('this.handleMarketData({', dropIndex);
    const tradeCycleIndex = source.indexOf('this.run15mTradingCycle(', dropIndex);
    const nextSelectorIndex = source.indexOf("if (tf === '5m' && this.timeframeSelector)", dropIndex);

    expect(dropIndex).toBeGreaterThan(-1);
    expect(nextSelectorIndex).toBeGreaterThan(dropIndex);
    expect(handleIndex === -1 || handleIndex > nextSelectorIndex).toBe(true);
    expect(tradeCycleIndex === -1 || tradeCycleIndex > nextSelectorIndex).toBe(true);
  });

  test('names non-active broker bars as mark-only before the strategy-frame branch', () => {
    const source = runEmpireSource();
    const handlerStart = source.indexOf('const ohlcHandler = (eventData) => {');
    const handlerEnd = source.indexOf('this.sessionRouter.wire(', handlerStart);
    const handler = source.slice(handlerStart, handlerEnd);
    const markIndex = handler.indexOf('stateManager.updateLastPrice(');
    const influenceIndex = handler.indexOf("emitTrace(this, 'LAST_PRICE_INFLUENCE'");
    const strategyBranchIndex = handler.indexOf('if (tf === activeTf)');

    expect(markIndex).toBeGreaterThan(-1);
    expect(influenceIndex).toBeGreaterThan(markIndex);
    expect(strategyBranchIndex).toBeGreaterThan(influenceIndex);
    expect(handler).toContain("influence: tf === activeTf ? 'mark_and_strategy' : 'mark_only'");
    expect(handler.match(/LAST_PRICE_INFLUENCE/g)).toHaveLength(1);
  });
});

